# ═══════════════════════════════════════════════════════════════
# HELPERS
# ═══════════════════════════════════════════════════════════════
SCHEMA_MAP = {
    'branch_opportunity_base':      'analytics',
    'bank_financial_snapshot_latest': 'analytics',
    'branch_target_competitors':    'analytics',
    'dim_institutions':             'ref',
    'bank_website':                 'ref',
}

def supabase(table, params):
    url = f"{SUPA_URL}/rest/v1/{table}?{params}"
    schema = SCHEMA_MAP.get(table, 'public')
    headers = {"apikey": SUPA_KEY, "Authorization": f"Bearer {SUPA_KEY}"}
    if schema != 'public':
        headers['Accept-Profile'] = schema
    r = requests.get(url, headers=headers, timeout=30)
    r.raise_for_status()
    return r.json()


def supabase_insert(table, payload):
    """POST helper, mirrors supabase()'s GET pattern above — used to cache
    generated personas so re-running the same bank doesn't produce a
    different narrative each time."""
    url = f"{SUPA_URL}/rest/v1/{table}"
    schema = SCHEMA_MAP.get(table, 'public')
    headers = {"apikey": SUPA_KEY, "Authorization": f"Bearer {SUPA_KEY}",
               "Content-Type": "application/json", "Prefer": "return=minimal"}
    if schema != 'public':
        headers['Content-Profile'] = schema
    r = requests.post(url, headers=headers, json=payload, timeout=30)
    r.raise_for_status()



