def build_persona_slide(prs, brief, bank_name, logo_bytes, page_num=5, transparent_logo_bytes=None, chevron_bytes=None):
    """
    Slide: Audience Intelligence Brief — mirrors the Hub's AudienceFinder brief:
    paragraph / named persona cards / where the opportunity is strong / where
    to validate / what this means for targeting. Same template as every other
    slide: white body, top-right logo, teal-rule headline, bottom banner.
    """
    slide = prs.slides.add_slide(prs.slide_layouts[6])

    # Same chrome as every other slide — top-right logo + bottom gradient banner
    add_chrome(slide, page_num, None, logo_bytes, transparent_logo_bytes, chevron_bytes)

    # Headline block — narrower box so it can't wrap into the logo/label corner
    add_text(slide, "YOUR MARKET IS TELLING YOU WHO TO TALK TO",
             0.7, 0.24, 6.9, 0.50, size=18, bold=True, color=NAVY, valign="bottom")
    add_rect(slide, 0.7, 0.80, 8.6, 0.04, TEAL)
    add_text(slide, f"First-level audience read across priority branches · {bank_name}",
             0.7, 0.87, 7.6, 0.20, size=9, italic=True, color=NAVY_SOFT)

    brief = brief or {}
    paragraph  = brief.get("paragraph", "")
    personas   = (brief.get("personas", []) or [])[:2]
    strong     = (brief.get("strong", []) or [])[:3]
    watch      = (brief.get("watch", []) or [])[:2]
    asymmetric = brief.get("asymmetric", "")

    y = 1.16

    # The audience in one paragraph
    add_text(slide, "THE AUDIENCE IN ONE PARAGRAPH", 0.7, y, 8.6, 0.14,
             size=7.5, bold=True, color=GRAY3)
    add_text(slide, paragraph, 0.7, y + 0.15, 8.6, 0.40,
             size=8.5, color=NAVY, shrink_to_fit=True)
    y += 0.60

    # Named persona cards — compact, 1 or 2 side by side
    if personas:
        add_text(slide, "AUDIENCE PERSONAS", 0.7, y, 8.6, 0.14,
                 size=7.5, bold=True, color=GRAY3)
        y += 0.16
        card_h = 1.05
        n = len(personas)
        card_w = 8.6 if n == 1 else 4.2
        gap = 0.2
        for i, p in enumerate(personas):
            cx = 0.7 + i * (card_w + gap)
            add_rect(slide, cx, y, card_w, card_h, rgb("F7F8FA"), rgb("DDE3EA"), Pt(0.5))
            add_text(slide, p.get("name", "—"), cx + 0.10, y + 0.05, card_w - 0.20, 0.18,
                     size=9.5, bold=True, color=NAVY)
            add_text(slide, p.get("descriptor", ""), cx + 0.10, y + 0.23, card_w - 0.20, 0.16,
                     size=7, italic=True, color=GRAY3)
            line1 = f"Life stage: {p.get('life_stage','—')}   ·   Wealth signal: {p.get('wealth_signal','—')}"
            line2 = f"Need: {p.get('primary_need','—')}   ·   Switch driver: {p.get('switch_driver','—')}"
            line3 = f"Markets: {p.get('markets','—')}"
            add_text(slide, line1, cx + 0.10, y + 0.42, card_w - 0.20, 0.20,
                     size=7, color=NAVY, shrink_to_fit=True)
            add_text(slide, line2, cx + 0.10, y + 0.63, card_w - 0.20, 0.20,
                     size=7, color=NAVY, shrink_to_fit=True)
            add_text(slide, line3, cx + 0.10, y + 0.84, card_w - 0.20, 0.18,
                     size=7, bold=True, color=GRAY3, shrink_to_fit=True)
        y += card_h + 0.08

    # Where the opportunity is strong
    add_text(slide, "WHERE THE OPPORTUNITY IS STRONG", 0.7, y, 8.6, 0.14,
             size=7.5, bold=True, color=GRAY3)
    y += 0.16
    for s in strong:
        tb = slide.shapes.add_textbox(Inches(0.7), Inches(y), Inches(8.6), Inches(0.24))
        tf = tb.text_frame; tf.word_wrap = True
        p = tf.paragraphs[0]
        r1 = p.add_run(); r1.text = "→  "; r1.font.bold = True; r1.font.color.rgb = TEAL; r1.font.size = Pt(8)
        r2 = p.add_run(); r2.text = s; r2.font.size = Pt(8); r2.font.color.rgb = NAVY
        for r in (r1, r2):
            r.font.name = "Inter"
        y += 0.25
    y += 0.05

    # Where to validate before activating
    add_text(slide, "WHERE TO VALIDATE BEFORE ACTIVATING", 0.7, y, 8.6, 0.14,
             size=7.5, bold=True, color=GRAY3)
    y += 0.16
    for s in watch:
        tb = slide.shapes.add_textbox(Inches(0.7), Inches(y), Inches(8.6), Inches(0.24))
        tf = tb.text_frame; tf.word_wrap = True
        p = tf.paragraphs[0]
        r1 = p.add_run(); r1.text = "→  "; r1.font.bold = True; r1.font.color.rgb = JUSTIFY; r1.font.size = Pt(8)
        r2 = p.add_run(); r2.text = s; r2.font.size = Pt(8); r2.font.color.rgb = NAVY
        for r in (r1, r2):
            r.font.name = "Inter"
        y += 0.25
    y += 0.06

    # What this means for targeting — callout box
    if asymmetric:
        box_h = 0.46
        add_rect(slide, 0.7, y, 8.6, box_h, rgb("F0FAFB"), rgb("D9F2F6"), Pt(0.75))
        add_text(slide, "WHAT THIS MEANS FOR TARGETING", 0.84, y + 0.04, 8.3, 0.13,
                 size=7, bold=True, color=GRAY3)
        add_text(slide, asymmetric, 0.84, y + 0.17, 8.3, box_h - 0.21,
                 size=8, color=NAVY, shrink_to_fit=True)

    return slide

def build_deck(data, logo_bytes):
    rows = data["rows"]; fin = data["fin"]; tgt = data["tgt"]
    br   = data["br"];   bankName = data["bankName"]

    def sf(v, default=0):
        """Safe float — handles None, empty string, missing."""
        try:
            return float(v) if v is not None else default
        except (TypeError, ValueError):
            return default

    tot      = sum(sf(r.get("latest_dep")) for r in rows)
    avg      = lambda v: sum(sf(r.get(v)) for r in rows) / max(len(rows),1)
    invest   = sum(1 for r in rows if r.get("opportunity_zone")=="Invest")
    analyze  = sum(1 for r in rows if r.get("opportunity_zone")=="Analyze")
    defend   = sum(1 for r in rows if r.get("opportunity_zone")=="Defend")
    justify  = sum(1 for r in rows if r.get("opportunity_zone")=="Justify")
    dep_invest  = sum(sf(r.get("latest_dep")) for r in rows if r.get("opportunity_zone")=="Invest")
    dep_analyze = sum(sf(r.get("latest_dep")) for r in rows if r.get("opportunity_zone")=="Analyze")
    dep_defend  = sum(sf(r.get("latest_dep")) for r in rows if r.get("opportunity_zone")=="Defend")
    dep_justify = sum(sf(r.get("latest_dep")) for r in rows if r.get("opportunity_zone")=="Justify")
    bankYoY  = avg("yoy_deposits")*100
    compYoY  = avg("avg_comp_yoy")*100
    gap      = bankYoY - compYoY
    avgScore = avg("opportunity_score")

    top_br   = sorted(br, key=lambda b: sf(b.get("opportunity_score")), reverse=True)
    just_top = sorted([b for b in br if b.get("opportunity_zone")=="Justify"],
                      key=lambda b: sf(b.get("latest_dep")), reverse=True)
    tier1    = [b for b in br if b.get("campaign") in ["Aggressive Acquisition","Urgent Competitive Push","Capitalize","Turnaround","Grow Share","Competitive Defense"]][:2]

    narr = get_narratives(data)

    D = {
        "bankName":    bankName,
        "date":        datetime.now().strftime("%B %Y"),
        "branchCount": str(len(rows)),
        "deposits":    f"${tot/1e9:.1f}B",
        "avgScore":    f"{avgScore:.0f}",
        "depositYoY":  f"{bankYoY:+.1f}%",
        "gap":         f"{gap:+.1f}pp",
        "bankYoY":     f"{bankYoY:.1f}",
        "peerYoY":     f"{compYoY:.1f}",
        "gapNeg":      gap < 0,
        "gapSubtitle": f"Deposit growth vs. peer average — {fin.get('period','Q4 2025')}",
        "invest":  invest,  "analyze": analyze,
        "defend":  defend,  "justify": justify,
        "depInvest":  dep_invest,  "depAnalyze": dep_analyze,
        "depDefend":  dep_defend,  "depJustify": dep_justify,
        "branchList": _build_branch_list(br, sf),
        "metrics": [
            {"label":"ROA",           "value":f"{sf(fin.get('roa')):.2f}%",              "bench":">1.0%",    "ok": sf(fin.get("roa"))>=1},
            {"label":"NIM",           "value":f"{sf(fin.get('nim')):.2f}%",              "bench":"2.5–3.5%", "ok": 2.5<=sf(fin.get("nim"))<=4},
            {"label":"Efficiency",    "value":f"{sf(fin.get('efficiency_ratio')):.2f}%", "bench":"<60%",     "ok": 0<sf(fin.get("efficiency_ratio"))<60},
            {"label":"Net Income YoY","value":f"{sf(fin.get('net_income_yoy_pct')):+.1f}%",               "bench":">0%",      "ok": sf(fin.get("net_income_yoy_pct"))>0},
            {"label":"Deposit YoY",   "value":f"{bankYoY:+.1f}%",                        "bench":">2%",      "ok": bankYoY>=2},
            {"label":"Cost of Funds", "value":f"{sf(fin.get('cost_of_funds_pct')):.2f}%","bench":"<2%",      "ok": 0<sf(fin.get("cost_of_funds_pct"))<2},
            {"label":"Tier 1 Capital","value":f"{sf(fin.get('tier1_capital_pct')):.2f}%","bench":">8%",      "ok": sf(fin.get("tier1_capital_pct"))>=8},
        ],
        "competitor": {
            "branches": tgt["branches_in_radius"],
            "yoy":      f"{sf(tgt.get('avg_yoy_pct')):.1f}",
            "vuln":     f"{sf(tgt.get('avg_vuln_score')):.0f}",
        } if tgt else None,
        "brokered": data.get("brokered"),
        "actions": [
            {
                "title": "BMAP — Market Truth",
                "body":  f"Full branch scoring across all {len(rows)} locations. Decision-quality clarity on where to invest, defend, and exit. The data foundation every other step builds on.",
            },
            {
                "title": "AudienceFinder & MediaPredict",
                "body":  f"Rate-sensitive depositor campaigns targeted to your top {invest} Invest-zone markets. Precision media that general spend can't replicate — savings openers converted into sticky CD relationships.",
            },
            {
                "title": "Omnibranch",
                "body":  "Unified branch-level orchestration — connects deposit data, market signals, and campaign execution into one operating view across the network.",
            },
            {
                "title": "Predictive ROI",
                "body":  "Forecasts the return on each marketing dollar before it's spent, then tracks performance against that forecast — accountability built into the system, not added after.",
            },
        ],
    }

    print(f"  Building slides...")
    prs = Presentation()
    prs.slide_width  = W
    prs.slide_height = H
    # Ensure blank layout exists
    while len(prs.slide_layouts) < 7:
        prs.slide_layouts.add_slide()

    transparent_logo_bytes = fetch_transparent_logo()
    chevron_bytes = fetch_chevron_mark()
    build_cover(prs, D, logo_bytes, transparent_logo_bytes, chevron_bytes)
    build_network(prs, D, narr, logo_bytes, page_num=2, transparent_logo_bytes=transparent_logo_bytes, chevron_bytes=chevron_bytes)

    # Lead/flagship office — highest-deposit branch, preferring one in DC if
    # present (matches how Tom/Brock refer to it: "the lead office in DC").
    # Falls back to highest-deposit branch generally if no DC branch exists.
    lead_branch = None
    if br:
        dc_branches = [b for b in br if (b.get("stalpbr") or "").upper() == "DC"]
        pool = dc_branches or br
        lead_branch = max(pool, key=lambda b: sf(b.get("latest_dep")))

    print(f"  Fetching competitor data for lead office...")
    competitors = fetch_branch_competitors(lead_branch.get("uninumbr")) if lead_branch else []
    competitors = filter_to_peer_institutions(competitors, ik)
    build_competitive_overview(prs, D, lead_branch, competitors, logo_bytes, page_num=3,
                                transparent_logo_bytes=transparent_logo_bytes, chevron_bytes=chevron_bytes)

    build_branches(prs, D, narr, logo_bytes, page_num=4, transparent_logo_bytes=transparent_logo_bytes, chevron_bytes=chevron_bytes)
    build_financial(prs, D, narr, logo_bytes, page_num=5, transparent_logo_bytes=transparent_logo_bytes, chevron_bytes=chevron_bytes)
    build_gap(prs, D, narr, logo_bytes, page_num=6, transparent_logo_bytes=transparent_logo_bytes, chevron_bytes=chevron_bytes)
    # Audience brief slide — before next steps
    brief = data.get("personas")
    next_page = 7
    if brief and brief.get("paragraph"):
        print(f"  Adding audience brief slide...")
        build_persona_slide(prs, brief, bankName, logo_bytes, page_num=7, transparent_logo_bytes=transparent_logo_bytes, chevron_bytes=chevron_bytes)
        next_page = 8
    else:
        print("  Skipping audience brief slide — no brief available")
    build_next_steps(prs, D, narr, logo_bytes, page_num=next_page, transparent_logo_bytes=transparent_logo_bytes, chevron_bytes=chevron_bytes)

    return prs


def save_deck(prs, bank_name, out_dir=OUT_DIR):
    safe = "".join(c if c.isalnum() or c in " _-" else "_" for c in bank_name).strip()
    date = datetime.now().strftime("%Y%m%d")
    fname = out_dir / f"BMAP_Snapshot_{safe}_{date}.pptx"
    prs.save(str(fname))
    return fname


